@prefix sh:       <http://www.w3.org/ns/shacl#> .
@prefix xsd:      <http://www.w3.org/2001/XMLSchema#> .

:DistributionShape a sh:NodeShape ;
  sh:targetClass dcat:Distribution ;
  sh:property [
    sh:path dct:issued ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ], [
    sh:path dct:modified ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ], [
    sh:path dcat:accessURL ;
    sh:nodeKind sh:IRI ;
    sh:maxCount 1 ;
    dash:editor dash:URIEditor ;
  ], [
    sh:path dcat:downloadURL ;
    sh:nodeKind sh:IRI ;
    sh:maxCount 1 ;
    dash:editor dash:URIEditor ;
  ], [
    sh:path dcat:mediaType ;
    sh:nodeKind sh:Literal ;
    sh:minCount 1 ;
    sh:maxCount 1 ;
    dash:editor dash:TextFieldEditor ;
    dash:viewer dash:LiteralViewer ;
  ], [
    sh:path dcat:format ;
    sh:nodeKind sh:Literal ;
    sh:maxCount 1 ;
    dash:editor dash:TextFieldEditor ;
    dash:viewer dash:LiteralViewer ;
  ], [
    sh:path dcat:byteSize ;
    sh:nodeKind sh:Literal ;
    sh:maxCount 1 ;
    dash:editor dash:TextFieldEditor ;
    dash:viewer dash:LiteralViewer ;
  ] .

@prefix :         <http://fairdatapoint.org/> .
@prefix dash:     <http://datashapes.org/dash#> .
@prefix dcat:     <http://www.w3.org/ns/dcat#> .
@prefix dct:      <http://purl.org/dc/terms/> .
@prefix sh:       <http://www.w3.org/ns/shacl#> .
@prefix xsd:      <http://www.w3.org/2001/XMLSchema#> .

:DataServiceShape a sh:NodeShape ;
  sh:targetClass dcat:DataService ;
  sh:property [
    sh:path dcat:endpointURL ;
    sh:nodeKind sh:IRI ;
    sh:maxCount 1 ;
  ] , [
    sh:path dcat:endpointDescription ;
    sh:nodeKind sh:Literal ;
    sh:maxCount 1 ;
    dash:editor dash:TextAreaEditor ;
    dash:viewer dash:LiteralViewer ;
] .

@prefix :         <http://fairdatapoint.org/> .
@prefix fdp:      <https://w3id.org/fdp/fdp-o#> .
@prefix sh:       <http://www.w3.org/ns/shacl#> .

:MetadataServiceShape a sh:NodeShape ;
  sh:targetClass fdp:MetadataService .

@prefix :         <http://fairdatapoint.org/> .
@prefix dash:     <http://datashapes.org/dash#> .
@prefix dct:      <http://purl.org/dc/terms/> .
@prefix fdp:      <https://w3id.org/fdp/fdp-o#> .
@prefix sh:       <http://www.w3.org/ns/shacl#> .
@prefix xsd:      <http://www.w3.org/2001/XMLSchema#> .

:FDPShape a sh:NodeShape ;
  sh:targetClass fdp:FAIRDataPoint ;
  sh:property [
    sh:path fdp:startDate ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ] , [
    sh:path fdp:endDate ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ] , [
    sh:path fdp:uiLanguage ;
    sh:nodeKind sh:IRI ;
    sh:maxCount 1 ;
    sh:defaultValue <http://id.loc.gov/vocabulary/iso639-1/en>;
    dash:editor dash:URIEditor ;
    dash:viewer dash:LabelViewer ;
  ] , [
    sh:path fdp:metadataIdentifier ;
    sh:nodeKind sh:IRI ;
    sh:maxCount 1 ;
    dash:editor dash:URIEditor ;
    dash:viewer dash:LabelViewer ;
  ] , [
    sh:path fdp:metadataIssued ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ] , [
    sh:path fdp:metadataModified ;
    sh:datatype xsd:dateTime ;
    sh:maxCount 1 ;
    dash:editor dash:DatePickerEditor ;
    dash:viewer dash:LiteralViewer ;
  ] .
